function dfs(nodes, edges, start){
  var adj={}; nodes.forEach(function(n){ adj[n]=[]; });
  edges.forEach(function(e){ adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); });
  var visited={}, order=[];
  (function rec(u){ visited[u]=true; order.push(u); adj[u].slice().sort().forEach(function(v){ if(!visited[v]) rec(v); }); })(start);
  return order;
}
var EXPORTS = { dfs:dfs };

